13	/**
14	 * Marks the request as coming from a trusted local Storybook client. `@storybook/addon-mcp` uses
15	 * this header to skip auth flows meant for remote (composed) Storybooks.
16	 */
17	const STORYBOOK_MCP_PROXY_HEADER = 'X-Storybook-MCP-Proxy';
18	const STORYBOOK_MCP_PROXY_HEADER_VALUE = 'true';
19	
20	/**
21	 * Upper bound on a single request so a hung server cannot stall the CLI forever. Generous because
22	 * `run-story-tests` on a full suite legitimately runs for minutes.
23	 */
24	const REQUEST_TIMEOUT_MS = 10 * 60 * 1000;
25	
26	/**
27	 * Identifies the CLI on the MCP connection, so `@storybook/addon-mcp`'s server-side `tool:*`
28	 * telemetry can segment CLI-originated calls from agents connected over MCP directly
29	 * (storybookjs/storybook#35131).
30	 */
31	export const MCP_CLIENT_INFO = { name: 'storybook-cli', version: versions.storybook };
32	
33	/** Protocol version sent on `initialize`; tmcp (the addon-mcp server library) supports it. */
34	const MCP_PROTOCOL_VERSION = '2025-06-18';
35	
36	/**
37	 * The handshake is telemetry garnish sitting on the critical path of every command, so its budget
38	 * must stay small: a local tmcp `initialize` answers in milliseconds, and a few seconds is already
39	 * generous headroom for a busy dev server. On timeout (or any other failure) the command simply
40	 * proceeds without clientInfo.
41	 */
42	const INITIALIZE_TIMEOUT_MS = 3 * 1000;
43	
44	export type ToolCallParams = {
45	  name: string;
46	  arguments?: Record<string, unknown>;
47	};
48	
49	/** A JSON-RPC level error returned by the Storybook MCP server (e.g. unknown tool). */
50	export class McpJsonRpcError extends Error {
51	  constructor(
52	    public readonly code: number,
53	    message: string
54	  ) {
55	    super(`Storybook server error ${code}: ${message}`);
56	    this.name = 'McpJsonRpcError';
57	  }
58	}
59	
60	const JsonRpcEnvelopeSchema = v.looseObject({
61	  result: v.optional(v.unknown()),
62	  error: v.optional(v.looseObject({ code: v.number(), message: v.string() })),
63	});
64	
65	const ToolListResultSchema = v.looseObject({
66	  tools: v.optional(v.array(McpToolDescriptorSchema)),
67	});
68	
69	/** Forward an MCP `tools/call` JSON-RPC request to a local Storybook MCP server. */
70	export async function callMcpTool(
71	  record: StorybookInstanceRecord,
72	  params: ToolCallParams,
73	  fetchImpl: typeof fetch = fetch
74	): Promise<ToolCallResult> {
75	  return sendJsonRpcRequest(record, 'tools/call', params, ToolCallResultSchema, fetchImpl);
76	}
77	
78	/** List the tools exposed by a local Storybook MCP server via `tools/list`. */
79	export async function listMcpTools(
80	  record: StorybookInstanceRecord,
81	  fetchImpl: typeof fetch = fetch
82	): Promise<McpToolDescriptor[]> {
83	  const result = await sendJsonRpcRequest(
84	    record,
85	    'tools/list',
86	    {},
87	    ToolListResultSchema,
88	    fetchImpl
89	  );
90	  return result.tools ?? [];
91	}
